# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">MEKKELİ MÜŞRİKLERİN İSLAM DAVETİNE TEPKİ GÖSTERME SEBEPLERİ (SYR.10.2.2)</text>\n  <rect x="18" y="42" width="160" height="175" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="98" y="62" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">1. DİNÎ SEBEPLER</text>\n  <text x="26" y="84" font-size="9.8" fill="#1e3a8a">• Tevhid inancının putperestliği</text>\n  <text x="26" y="100" font-size="9.8" fill="#1e3a8a">  ve şefaatçi putları reddetmesi</text>\n  <text x="26" y="120" font-size="9.8" fill="#1e3a8a">• «Atalar dini» (kör taklit) ve</text>\n  <text x="26" y="136" font-size="9.8" fill="#1e3a8a">  gelenek taassubu</text>\n  <text x="26" y="156" font-size="9.8" fill="#1e3a8a">• Öldükten sonra dirilişi (haşir)</text>\n  <text x="26" y="172" font-size="9.8" fill="#1e3a8a">  ve hesap vermeyi inkâr</text>\n  <rect x="186" y="42" width="160" height="175" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="266" y="62" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">2. SOSYAL SEBEPLER</text>\n  <text x="194" y="84" font-size="9.8" fill="#14532d">• Köle ile efendiyi, yoksul ile</text>\n  <text x="194" y="100" font-size="9.8" fill="#14532d">  zengini eşit kılan İslam</text>\n  <text x="194" y="116" font-size="9.8" fill="#14532d">  kardeşliğini kabullenememe</text>\n  <text x="194" y="136" font-size="9.8" fill="#14532d">• Sınıf ayrımcılığının ve kibir</text>\n  <text x="194" y="152" font-size="9.8" fill="#14532d">  düzeninin sarsılması</text>\n  <text x="194" y="172" font-size="9.8" fill="#14532d">• Üstünlüğün yalnız takvada</text>\n  <text x="194" y="188" font-size="9.8" fill="#14532d">  olması ilkesine itiraz</text>\n  <rect x="354" y="42" width="160" height="175" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="434" y="62" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">3. SİYASİ SEBEPLER</text>\n  <text x="362" y="84" font-size="9.8" fill="#78350f">• Kabilecilik (asabiyet) ve</text>\n  <text x="362" y="100" font-size="9.8" fill="#78350f">  Haşimoğulları-Ümeyye/Mahzûm</text>\n  <text x="362" y="116" font-size="9.8" fill="#78350f">  liderlik rekabeti</text>\n  <text x="362" y="136" font-size="9.8" fill="#78350f">• Dârünnedve\'deki siyasi</text>\n  <text x="362" y="152" font-size="9.8" fill="#78350f">  otoriteyi kaybetme korkusu</text>\n  <text x="362" y="172" font-size="9.8" fill="#78350f">• Peygamberliği dünyevi bir</text>\n  <text x="362" y="188" font-size="9.8" fill="#78350f">  krallık/saltanat sanmaları</text>\n  <rect x="522" y="42" width="160" height="175" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="602" y="62" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">4. EKONOMİK SEBEPLER</text>\n  <text x="530" y="84" font-size="9.8" fill="#581c87">• Putlu Kâbe ziyareti ve panayır</text>\n  <text x="530" y="100" font-size="9.8" fill="#581c87">  gelirlerinin kesileceği korkusu</text>\n  <text x="530" y="120" font-size="9.8" fill="#581c87">• Faiz (ribâ), tefecilik, ölçü-</text>\n  <text x="530" y="136" font-size="9.8" fill="#581c87">  tartı hilesi ve yetim malı</text>\n  <text x="530" y="152" font-size="9.8" fill="#581c87">  yeme düzeninin yasaklanması</text>\n  <text x="530" y="172" font-size="9.8" fill="#581c87">• Köle emeği sömürüsünün ve</text>\n  <text x="530" y="188" font-size="9.8" fill="#581c87">  haksız kazancın son bulması</text>\n  <rect x="18" y="224" width="664" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Müşrikler, Hz. Peygamber\'in «el-Emîn» olduğunu bildikleri hâlde çıkar ve imtiyazlarını kaybetmemek için direnmiştir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">MÜŞRİKLERİN İSLAM DAVETİNİ ENGELLEMEK İÇİN BAŞVURDUKLARI YÖNTEMLER</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">AŞAMA 1: PSİKOLOJİK HARP VE UZLAŞMA TEKLİFİ</text>\n  <text x="32" y="88" font-size="10.5" fill="#7f1d1d">• Alay ve Küçümseme: Müslümanları ve vahyi hafife alma.</text>\n  <text x="32" y="108" font-size="10.5" fill="#7f1d1d">• İftira ve Karalama: Peygamberimize «şair, kâhin, sihirbaz,</text>\n  <text x="32" y="124" font-size="10.5" fill="#7f1d1d">  mecnun», Kur\'an\'a «eskilerin masalları (esâtîru\'l-evvelîn)»</text>\n  <text x="32" y="140" font-size="10.5" fill="#7f1d1d">  diyerek dışarıdan gelen hacıları etkilemeye çalışma.</text>\n  <text x="32" y="160" font-size="10.5" fill="#7f1d1d">• Gürültü Çıkarma: Kur\'an okunurken ıslık ve el çırpma.</text>\n  <text x="32" y="180" font-size="10.5" font-weight="bold" fill="#991b1b">• Uzlaşma Teklifi: Mal, makam veya dönüşümlü ibadet teklifi</text>\n  <text x="32" y="196" font-size="10.2" fill="#7f1d1d">  (Kâfirûn suresi ile kesin olarak reddedilmiştir!).</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">AŞAMA 2: FİZİKSEL İŞKENCE, BOYKOT VE SUİKAST</text>\n  <text x="372" y="88" font-size="10.5" fill="#7c2d12">• Ebû Talib\'e Baskı: Peygamberimizi himayeden vazgeçirme.</text>\n  <text x="372" y="108" font-size="10.5" fill="#7c2d12">• İşkence ve Şehadet: Köle ve kimsesiz müminlere işkence</text>\n  <text x="372" y="124" font-size="10.5" font-weight="bold" fill="#9a3412">  (İlk şehitler: Hz. Sümeyye ve eşi Hz. Yâsir; Habbâb, Bilâl).</text>\n  <text x="372" y="144" font-size="10.5" fill="#7c2d12">• Sosyal ve Ekonomik Boykot (616-619): Şi\'b-i Ebî Talib</text>\n  <text x="372" y="160" font-size="10.5" fill="#7c2d12">  mahallesinde 3 yıl süren açlık ve tecrit ablukası.</text>\n  <text x="372" y="180" font-size="10.5" font-weight="bold" fill="#9a3412">• Dârünnedve Suikast Kararı (622): Her kabileden bir</text>\n  <text x="372" y="196" font-size="10.2" fill="#7c2d12">  gençle Peygamberimizi evinde şehit etme planı.</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">«Güneşi sağ elime, ayı da sol elime verseler vallahi bu davadan vazgeçmem!» — Hz. Muhammed (s.a.v.)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">MÜŞRİK ÖNCÜLERİ VE PEYGAMBERİMİZİN NEBEVİ DURUŞU</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#f1f5f9" stroke="#475569" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e293b">MÜŞRİK MUHALEFETİNİN BAŞLICA AKTÖRLERİ</text>\n  <text x="32" y="88" font-size="10.5" fill="#334155">• Ebû Cehil (Amr b. Hişâm): İnkâr ve işkencenin elebaşı.</text>\n  <text x="32" y="108" font-size="10.5" fill="#334155">• Ebû Leheb ve karısı Ümmü Cemîl: Tebbet suresine konu</text>\n  <text x="32" y="124" font-size="10.5" fill="#334155">  olan, açık davet gününden itibaren düşmanlık eden amcası.</text>\n  <text x="32" y="144" font-size="10.5" fill="#334155">• Velîd b. Muğîre: Kur\'an\'ın belagati karşısında sarsıldığı</text>\n  <text x="32" y="160" font-size="10.5" fill="#334155">  hâlde kibrinden «Bu olsa olsa etkileyici bir sihirdir» diyen.</text>\n  <text x="32" y="180" font-size="10.5" fill="#334155">• Ümeyye b. Halef, Ukbe b. Ebî Muayt, Nadr b. Hâris.</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#065f46">PEYGAMBERİMİZİN VE ASHABININ KARARLILIĞI</text>\n  <text x="372" y="88" font-size="10.5" fill="#064e3b">• Sabır ve Sebat: İşkencelere karşı şiddete başvurmadan</text>\n  <text x="372" y="106" font-size="10.5" fill="#064e3b">  vakarla direnme («Sabredin ey Yâsir ailesi! Yerinizi cennettir»).</text>\n  <text x="372" y="126" font-size="10.5" fill="#064e3b">• Tevhidde Tavizsizlik: Kâfirûn suresi ile uzlaşma ve</text>\n  <text x="372" y="144" font-size="10.5" fill="#064e3b">  putperestlikle sentez tekliflerini kesin olarak reddetme.</text>\n  <text x="372" y="164" font-size="10.5" fill="#064e3b">• Yeni Ufuklar Arama: Mazlumları Habeşistan\'a gönderme,</text>\n  <text x="372" y="182" font-size="10.5" fill="#064e3b">  Tâif seferi ve Akabe Biatlarıyla Medine\'ye hicret hazırlığı.</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Müşriklerin 13 yıllık baskısı İslam nurunu söndürememiş; aksine müminlerin imanını çelikleştirmiştir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
